# D2S Level 1 uses every ordered selection of three toys from this four-toy
# pool exactly once (4P3 = 24).  The list order is the conveyor arrival order:
# source_objects[0], source_objects[1], and source_objects[2] occupy slots
# 1, 2, and 3 respectively.  Ordinals 1--12 have positive belt speed; 13--24
# have negative belt speed.  The split is complementary rather than repeating
# the same twelve sequences in the opposite direction.
_D2S_LV1_SOURCE_SEQUENCES = (
    ("school_bus_upright", "mario_flat", "thomas_upright"),
    ("school_bus_upright", "thomas_upright", "porter_upright"),
    ("school_bus_upright", "porter_upright", "mario_flat"),
    ("mario_flat", "school_bus_upright", "porter_upright"),
    ("mario_flat", "thomas_upright", "school_bus_upright"),
    ("mario_flat", "porter_upright", "thomas_upright"),
    ("thomas_upright", "school_bus_upright", "mario_flat"),
    ("thomas_upright", "mario_flat", "porter_upright"),
    ("thomas_upright", "porter_upright", "school_bus_upright"),
    ("porter_upright", "school_bus_upright", "thomas_upright"),
    ("porter_upright", "mario_flat", "school_bus_upright"),
    ("porter_upright", "thomas_upright", "mario_flat"),
    ("school_bus_upright", "mario_flat", "porter_upright"),
    ("school_bus_upright", "thomas_upright", "mario_flat"),
    ("school_bus_upright", "porter_upright", "thomas_upright"),
    ("mario_flat", "school_bus_upright", "thomas_upright"),
    ("mario_flat", "thomas_upright", "porter_upright"),
    ("mario_flat", "porter_upright", "school_bus_upright"),
    ("thomas_upright", "school_bus_upright", "porter_upright"),
    ("thomas_upright", "mario_flat", "school_bus_upright"),
    ("thomas_upright", "porter_upright", "mario_flat"),
    ("porter_upright", "school_bus_upright", "mario_flat"),
    ("porter_upright", "mario_flat", "thomas_upright"),
    ("porter_upright", "thomas_upright", "school_bus_upright"),
)
_D2S_LV1_TASK_KEYS = tuple(
    task_name
    for task_name in industry_object_map
    if task_name.startswith("D2S_LV1_")
)
if len(_D2S_LV1_TASK_KEYS) != len(_D2S_LV1_SOURCE_SEQUENCES):
    raise AssertionError("D2S Level 1 must contain 24 tasks")
for _task_name, _source_sequence in zip(
    _D2S_LV1_TASK_KEYS, _D2S_LV1_SOURCE_SEQUENCES
):
    # Level 1 places every conveyor object on one tray, so its goal set is
    # precisely the selected source set; it has no designated single target.
    industry_object_map[_task_name]["source_objects"] = list(_source_sequence)
    industry_object_map[_task_name]["target_objects"] = list(_source_sequence)
del _D2S_LV1_TASK_KEYS, _D2S_LV1_SOURCE_SEQUENCES, _task_name, _source_sequence


